import React, { useEffect, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import axios from 'axios';

const Comparison = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { results, selectedFeatures, videoURL, localVideoPath, seoData, optimizationType, aspectRatio } = location.state || {};
  const [originalSeoData, setOriginalSeoData] = useState(null);
  const [error, setError] = useState(null);
  const [processing, setProcessing] = useState(false);

  const fetchOriginalSeo = async () => {
    try {
      const response = await axios.get(`/api/get-original-seo`, {
        params: { url: videoURL },
      });
      setOriginalSeoData(response.data);
      setError(null);
    } catch (err) {
      console.error('Error fetching original SEO data:', err);
      setError('Failed to fetch SEO data.');
    }
  };

  useEffect(() => {
    if (selectedFeatures.includes('SEO')) {
      fetchOriginalSeo();
    }
  }, [videoURL, selectedFeatures]);

  const handleOptimization = async () => {
    if (optimizationType === 'Long Form' && !selectedFeatures.includes('SEO')) {
      setProcessing(true);
      try {
        console.log('Running video optimization...');
        console.log('Local Video Path:', localVideoPath);

        const payload = {
          videoURL,
          optimizationType,
          aspectRatio,
          selectedFeatures,
          localVideoPath,
        };

        const csrfToken = document.cookie
          .split('; ')
          .find((row) => row.startsWith('csrftoken'))
          ?.split('=')[1];

        const response = await axios.post(
          'http://127.0.0.1:8000/api/seo/',
          payload,
          {
            headers: {
              'X-CSRFToken': csrfToken,
              'Content-Type': 'application/json',
            },
          }
        );

        console.log('Response Data:', response.data);
        alert(response.data.message || 'Video optimization started!');

        navigate('/optimizevideo', {
          state: {
            videoURL,
            results: response.data.results,
            localVideoPath,
            selectedFeatures,
          },
        });
      } catch (error) {
        console.error('Error during optimization:', error);
        alert('Video optimization failed.');
      } finally {
        setProcessing(false);
      }
    }
  };

  const getProcessedVideoPath = () => {
    if (results?.audio_processing?.enhanced_video_path) {
      const filename = results.audio_processing.enhanced_video_path.split('\\').pop();
      return `http://127.0.0.1:8000/media/${filename}`;
    }
    if (results?.video_upscaling?.processed_file_path) {
      const filename = results.video_upscaling.processed_file_path.split('\\').pop();
      return `http://127.0.0.1:8000/media/${filename}`;
    }
    return null;
  };

  const processedVideoPath = getProcessedVideoPath();

  const calculateImprovement = (original, optimized) => {
    const originalLength = original?.length || 0;
    const optimizedLength = optimized?.length || 0;
    if (originalLength === 0) return '0%';
    const improvement = ((optimizedLength - originalLength) / originalLength * 100).toFixed(1);
    return `${improvement}%`;
  };

  const renderSeoComparison = () => {
    if (!originalSeoData || !seoData) return null;

    return (
      <div className="grid grid-cols-2 gap-6">
        {/* Original SEO Metrics */}
        <div className="p-4 border rounded-lg shadow-sm">
          <h3 className="text-lg font-bold mb-4">Original SEO Metrics</h3>
          <div className="space-y-4">
            <div>
              <h4 className="font-medium">Title</h4>
              <p className="text-sm mt-1">{originalSeoData.original_title}</p>
            </div>
            <div>
              <h4 className="font-medium">Description</h4>
              <p className="text-sm mt-1">{originalSeoData.original_description}</p>
            </div>
            <div>
              <h4 className="font-medium">Tags</h4>
              <p className="text-sm mt-1">{originalSeoData.original_tags.join(', ') || 'No tags'}</p>
            </div>
          </div>
        </div>

        {/* Optimized SEO Metrics */}
        <div className="p-4 border rounded-lg shadow-sm">
          <h3 className="text-lg font-bold mb-4">Optimized SEO Metrics</h3>
          <div className="space-y-4">
            <div>
              <h4 className="font-medium">Title</h4>
              <p className="text-sm mt-1">{seoData.title}</p>
              <p className="text-xs text-green-600 mt-1">
                Improvement: {calculateImprovement(originalSeoData.original_title, seoData.title)}
              </p>
            </div>
            <div>
              <h4 className="font-medium">Description</h4>
              <p className="text-sm mt-1">{seoData.description}</p>
              <p className="text-xs text-green-600 mt-1">
                Improvement: {calculateImprovement(originalSeoData.original_description, seoData.description)}
              </p>
            </div>
            <div>
              <h4 className="font-medium">Tags</h4>
              <p className="text-sm mt-1">{seoData.tags.join(', ') || 'No tags'}</p>
              <p className="text-xs text-green-600 mt-1">
                Improvement: {calculateImprovement(originalSeoData.original_tags, seoData.tags)}
              </p>
            </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <h1 className="text-3xl font-bold mb-8">Video Optimization Comparison</h1>

      {selectedFeatures.includes('Video Quality') && (
        <div className="grid grid-cols-2 gap-6 mb-8">
          <div>
            <h2 className="text-xl font-semibold mb-4">Original Video</h2>
            <video src={localVideoPath} controls className="w-full rounded-lg shadow-lg" />
          </div>
          <div>
            <h2 className="text-xl font-semibold mb-4">Optimized Video</h2>
            <video src={processedVideoPath} controls className="w-full rounded-lg shadow-lg" />
          </div>
        </div>
      )}

      {selectedFeatures.includes('SEO') && renderSeoComparison()}

      {!processing && (
        <button
          className="mt-6 px-4 py-2 bg-blue-600 text-white rounded-lg"
          onClick={handleOptimization}
        >
          Start Optimization
        </button>
      )}
    </div>
  );
};

export default Comparison;
